<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';
import { request,errorText,uid,APIError } from '../api';import { explicitRejection } from '../workflow';import { session } from '../session';import type { Change,ConfigurationState,Configuration,Plan,Job } from '../types';
const change=ref<Change>();const plan=ref<Plan>();const text=ref('');const recoveryId=ref(sessionStorage.getItem('sdn.change')||'');const busy=ref(false);const error=ref('');const notice=ref('');const dirty=ref(false);const router=useRouter();const pendingCommit=ref(sessionStorage.getItem('sdn.commit')||'');
const canEdit=computed(()=>session.role==='admin'&&!!change.value&&!change.value.frozen&&!change.value.aborted&&!pendingCommit.value);
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function accept(c:Change){change.value=c;text.value=JSON.stringify(c.configuration,null,2);dirty.value=false;plan.value=undefined;recoveryId.value=c.id;sessionStorage.setItem('sdn.change',c.id);}
async function create(){await action(async()=>{let pending=sessionStorage.getItem('sdn.begin');if(!pending){const desired=await request<ConfigurationState>('/desired');pending=JSON.stringify({baseRevision:desired.revision,requestId:uid()});sessionStorage.setItem('sdn.begin',pending);}const q=JSON.parse(pending);try{const c=await request<Change>('/changes',{method:'POST',body:q,key:q.requestId});sessionStorage.removeItem('sdn.begin');accept(c);}catch(e){if(e instanceof APIError&&explicitRejection(e.status))sessionStorage.removeItem('sdn.begin');throw e;}});}
async function recover(){if(!recoveryId.value)return;await action(async()=>{accept(await request<Change>(`/changes/${encodeURIComponent(recoveryId.value)}`));});}
async function save(){await action(async()=>{if(!change.value)return;const configuration=JSON.parse(text.value) as Configuration;if(!configuration||!Array.isArray(configuration.nodes)||!Array.isArray(configuration.tenants)||!Array.isArray(configuration.networks))throw new Error('完整配置必须包含 nodes、tenants、networks 三个数组');accept(await request<Change>(`/changes/${change.value.id}`,{method:'PUT',body:{configuration,editRevision:change.value.editRevision}}));notice.value='候选已保存；尚未下发。';});}
async function preview(){await action(async()=>{if(!change.value)return;plan.value=await request<Plan>(`/changes/${change.value.id}/plan`,{method:'POST'});});}
async function commit(){await action(async()=>{let pending=pendingCommit.value;if(!pending){if(!change.value||!plan.value)return;pending=JSON.stringify({changeId:change.value.id,planId:plan.value.id,requestId:uid()});sessionStorage.setItem('sdn.commit',pending);pendingCommit.value=pending;}const q=JSON.parse(pending);try{const job=await request<Job>(`/changes/${q.changeId}/commit`,{method:'POST',body:{planId:q.planId,requestId:q.requestId},key:q.requestId});clearPending();await router.push({path:'/jobs',query:{id:job.id}});}catch(e){
  if(e instanceof APIError&&explicitRejection(e.status)){
    try{const current=await request<Change>(`/changes/${q.changeId}`);if(current.jobId){clearPending();await router.push({path:'/jobs',query:{id:current.jobId}});return;}if(!current.frozen){clearPending();plan.value=undefined;notice.value='Controller 已拒绝此次提交，候选未冻结。可重新预览；基础版本冲突时请新建候选并合并修改。';throw e;}}catch(lookup){if(!pendingCommit.value)throw lookup;}
  }
  notice.value='提交结果尚未确认。保留原请求，可重试找回任务；不要重新创建变更。';throw e;
}});}
function clearPending(){sessionStorage.removeItem('sdn.commit');pendingCommit.value='';}
async function abort(){await action(async()=>{if(!change.value)return;await request(`/changes/${change.value.id}`,{method:'DELETE'});await recover();});}
function edited(){dirty.value=true;plan.value=undefined;}
onMounted(()=>{if(recoveryId.value)void recover();});
</script>
<template><section class="sdn-page"><div class="page-head"><div><h1>配置变更</h1><p class="subtitle">读取完整配置 → 编辑候选 → 预览计划 → 显式提交。</p></div><el-button v-if="session.role==='admin'" type="primary" :disabled="busy||!!pendingCommit" @click="create">新建候选</el-button></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><el-alert v-if="notice" type="info" :title="notice" :closable="false"/><el-alert v-if="session.role==='viewer'" type="info" title="只读用户可查看已知候选，不能修改或提交。" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="recoveryId" placeholder="输入 change_id 恢复候选" aria-label="候选 ID" style="max-width:420px"/><el-button :disabled="busy||!recoveryId" @click="recover">恢复候选</el-button></div><template v-if="change"><p class="subtitle mono">{{change.id}} · 基础版本 {{change.baseRevision}} · 草稿版本 {{change.editRevision}} · {{change.frozen?'已冻结':change.aborted?'已丢弃':'可编辑'}}</p><p class="subtitle">此编辑器替换完整资源配置，请保留其他节点、租户和网络。所有资源规则由 Controller 校验。</p><el-input v-model="text" class="json-editor" type="textarea" :rows="22" :readonly="!canEdit||busy" aria-label="完整资源配置 JSON" @input="edited"/><div class="toolbar" style="margin-top:18px"><el-button v-if="session.role==='admin'" :disabled="!canEdit||busy||!dirty" @click="save">保存候选</el-button><el-button v-if="session.role==='admin'" type="primary" plain :disabled="!canEdit||busy||dirty" @click="preview">预览计划</el-button><el-popconfirm v-if="session.role==='admin'" title="确认丢弃未提交候选？" @confirm="abort"><template #reference><el-button :disabled="!canEdit||busy">丢弃候选</el-button></template></el-popconfirm><span v-if="dirty" class="muted">修改尚未保存，需重新预览。</span></div><el-button v-if="change.jobId" link type="primary" @click="router.push({path:'/jobs',query:{id:change.jobId}})">查看已提交任务</el-button></template><el-empty v-else description="新建候选或恢复已知候选，开始配置"/></div><div v-if="plan" class="panel"><h2>下发计划</h2><p class="subtitle mono">{{plan.id}} · {{plan.nodes.length}} 个节点</p><el-alert v-for="warning in plan.warnings" :key="warning" :title="warning" type="warning" :closable="false"/><el-table :data="plan.nodes"><el-table-column type="expand"><template #default="{row}"><pre class="code">{{JSON.stringify(row.operations,null,2)}}</pre></template></el-table-column><el-table-column prop="nodeId" label="节点 ID"/><el-table-column prop="expectedAgentRevision" label="Agent 基础版本"/><el-table-column label="操作数"><template #default="{row}">{{row.operations.length}}</template></el-table-column></el-table><el-popconfirm title="确认提交此计划并开始配置网络？" @confirm="commit"><template #reference><el-button type="primary" :loading="busy" :disabled="dirty||!!pendingCommit||session.role!=='admin'" style="margin-top:20px">提交配置</el-button></template></el-popconfirm></div><div v-if="pendingCommit&&session.role==='admin'" class="panel"><el-alert type="warning" title="存在待确认的提交请求，使用原幂等键重试获取结果。" :closable="false"/><el-button :loading="busy" @click="commit">重试原提交</el-button></div></section></template>
